<?php
namespace App\Http\Controllers;
use App\Models\{Order,Product};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Inertia\Inertia;
class CheckoutController extends Controller {
 public function index(){if(empty(session('cart',[])))return redirect()->route('shop.cart');return Inertia::render('Shop/Checkout',['cart'=>session('cart',[])]);}
 public function store(Request $request){$data=$request->validate(['customer_name'=>'required|string|max:120','phone'=>'required|string|max:30','address'=>'required|string|max:1000','payment_method'=>'required|in:transfer,cod']);$cart=session('cart',[]);abort_if(empty($cart),redirect()->route('shop.index'));$order=DB::transaction(function()use($cart,$data,$request){$products=Product::whereIn('id',array_keys($cart))->lockForUpdate()->get()->keyBy('id');$total=0;$lines=[];foreach($cart as $id=>$row){$p=$products->get($id);abort_unless($p && $p->stock >= $row['qty'],422,'Stok produk berubah. Silakan periksa keranjang.');$subtotal=$p->price*$row['qty'];$total+=$subtotal;$lines[]=[$p,$row['qty'],$subtotal];}$order=Order::create(['user_id'=>$request->user()->id,'order_number'=>'TK'.now()->format('ymd').str()->upper()->random(5),'customer_name'=>$data['customer_name'],'phone'=>$data['phone'],'address'=>$data['address'],'total'=>$total,'status'=>'pending','payment_method'=>$data['payment_method']]);foreach($lines as [$p,$qty,$subtotal]){$order->items()->create(['product_id'=>$p->id,'product_name'=>$p->name,'price'=>$p->price,'qty'=>$qty,'subtotal'=>$subtotal]);$p->decrement('stock',$qty);}return $order;});session()->forget('cart');return redirect()->route('orders.show',$order)->with('success','Pesanan berhasil dibuat.');}
 public function show(Order $order,Request $request){abort_unless($order->user_id===$request->user()->id || $request->user()->role==='admin',403);$order->load('items');return Inertia::render('Shop/OrderShow',['order'=>$order]);}
 public function history(Request $request){return Inertia::render('Shop/Orders',['orders'=>$request->user()->orders()->with('items')->latest()->paginate(10)]);}
}
